import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// the World's registry, as cookbook/tabnode's seed.mjs reads it (NPM_REGISTRY_TWIN_URL), and the token the World's
// credential door issued as NPM_TOKEN
export const registry = process.env.NPM_REGISTRY_TWIN_URL;
if (!registry || !process.env.NPM_TOKEN) throw new Error('The World names its registry and issues the token');
const userconfig = join(process.cwd(), 'publish.npmrc');
writeFileSync(userconfig, `registry=${registry}\n//${new URL(registry).host}${new URL(registry).pathname.replace(/\/?$/, '/')}:_authToken=${process.env.NPM_TOKEN}\n`, { mode: 0o600 });
// npm's own entry (its bin), the app's pinned install
const cli = join(dirname(createRequire(import.meta.url).resolve('npm/package.json')), 'bin', 'npm-cli.js');
/** npm itself, the app's pinned version, against the World's registry; each run with a cache of its own so every read
 *  reaches the registry. */
export function npm(args, cache, cwd = process.cwd()) {
  const r = spawnSync(process.execPath, [cli, ...args, '--registry', registry, '--userconfig', userconfig, '--cache', join(process.cwd(), cache)], { cwd, encoding: 'utf8' });
  if (r.status !== 0) throw new Error(`npm ${args.join(' ')} exited ${r.status}: ${r.stderr.slice(-1500)}`);
  return r.stdout;
}
/** A fresh project that installs the package from the registry, as a consumer does, and runs it. */
export function installAndRun(at, spec, cache) {
  const dir = resolve(at);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'package.json'), JSON.stringify({ name: 'studio-batch', private: true }) + '\n');
  npm(['install', spec, '--no-audit', '--no-fund', '--ignore-scripts'], cache, dir);
  const lock = JSON.parse(readFileSync(join(dir, 'package-lock.json'), 'utf8'));
  const { scale } = createRequire(join(dir, 'package.json'))('glaze-calc');
  return { lock: lock.packages['node_modules/glaze-calc'], batch: scale({ silica: 30, kaolin: 20, feldspar: 50 }, 5000) };
}

