import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { installAndRun, npm } from './npm.mjs';

// the studio publishes its package with npm, as a release does (npm publish --access public)
npm(['publish', './glaze', '--access', 'public', '--provenance=false', '--ignore-scripts'], '.cache-publish');
// the registry's document for it: its version and its tarball's integrity
const view = JSON.parse(npm(['view', 'glaze-calc', '--json'], '.cache-view'));
assert.equal(view.name, 'glaze-calc');
assert.equal(view.version, '1.0.0');
assert.deepEqual(view['dist-tags'], { latest: '1.0.0' });
assert.match(view.dist.integrity, /^sha512-/);
assert.match(view.dist.tarball, /\/glaze-calc\/-\/glaze-calc-1\.0\.0\.tgz$/);
// its channels, as an update check reads them (GET /-/package/<name>/dist-tags)
assert.match(npm(['dist-tag', 'ls', 'glaze-calc'], '.cache-tags'), /^latest: 1\.0\.0$/m);
// a consumer installs it from the registry: the lockfile pins the published tarball, and the code runs
const installed = installAndRun('consumer', 'glaze-calc@^1.0.0', '.cache-install');
assert.equal(installed.lock.version, '1.0.0');
assert.equal(installed.lock.integrity, view.dist.integrity);
assert.deepEqual(installed.batch, { silica: 1500, kaolin: 1000, feldspar: 2500 });
writeFileSync('release.json', JSON.stringify({ integrity: view.dist.integrity, tarball: view.dist.tarball }) + '\n');
console.log(JSON.stringify({ published: `${view.name}@${view.version}`, integrity: view.dist.integrity, batch: installed.batch }));

