import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { installAndRun, npm } from './npm.mjs';

// after the World resumes: the registry still holds the release the run published, and a new consumer installs the
// same bytes (fresh caches: every read reaches the registry; nothing is published again)
const release = JSON.parse(readFileSync('release.json', 'utf8'));
const view = JSON.parse(npm(['view', 'glaze-calc@1.0.0', '--json'], '.cache-readback-view'));
assert.equal(view.dist.integrity, release.integrity);
// the tarball is addressed on the registry's host, which the resumed World serves at its new port
assert.equal(new URL(view.dist.tarball).pathname, new URL(release.tarball).pathname);
const installed = installAndRun('consumer-after-resume', 'glaze-calc@1.0.0', '.cache-readback-install');
assert.equal(installed.lock.integrity, release.integrity);
assert.deepEqual(installed.batch, { silica: 1500, kaolin: 1000, feldspar: 2500 });
console.log(JSON.stringify({ integrity: view.dist.integrity, batch: installed.batch }));
